```java
public class BubbleSort {

    /**
     * Sorts an integer array in ascending order using Bubble Sort.
     * Handles duplicates, negative numbers, and zero.
     *
     * @param arr the input array to be sorted
     * @return a new array containing the sorted elements
     */
    public static int[] bubbleSort(int[] arr) {
        if (arr == null || arr.length <= 1) {
            // Return a copy to avoid modifying the original if needed
            if (arr == null) return null;
            return arr.clone();
        }

        int n = arr.length;
        int[] result = arr.clone(); // Work on a copy

        boolean swapped;
        for (int i = 0; i < n - 1; i++) {
            swapped = false;
            // Last i elements are already in place
            for (int j = 0; j < n - 1 - i; j++) {
                if (result[j] > result[j + 1]) {
                    // Swap
                    int temp = result[j];
                    result[j] = result[j + 1];
                    result[j + 1] = temp;
                    swapped = true;
                }
            }
            // If no two elements were swapped, the array is already sorted
            if (!swapped) {
                break;
            }
        }

        return result;
    }

    // Example usage
    public static void main(String[] args) {
        int[] input = {5, -2, 0, 3, 3, -1, 7};
        int[] sorted = bubbleSort(input);

        for (int num : sorted) {
            System.out.print(num + " ");
        }
        // Output: -2 -1 0 3 3 5 7
    }
}
